* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, sans-serif; font-size: 16px; }
body { min-height: 100vh; margin: 0; padding: 24px 16px; display: grid; place-items: center; color: #252443; background-color: #dff4ed; background-image: radial-gradient(#9acdbb 1.5px, transparent 1.5px); background-size: 22px 22px; }
.card { width: min(100%, 420px); padding: 32px clamp(20px, 7vw, 38px) 28px; text-align: center; background: #fffaf0; border: 4px solid #252443; box-shadow: 8px 8px 0 #252443; }
.avatar { width: 76px; height: 76px; margin: 0 auto 18px; display: grid; place-items: center; background: #f5ad68; border: 4px solid #252443; box-shadow: 4px 4px 0 #252443; image-rendering: pixelated; }
.avatar span { color: #fffaf0; font-size: 40px; line-height: 1; text-shadow: 2px 2px #252443; }
.eyebrow, .bio-label { margin: 0; color: #527c70; font-size: 0.78rem; font-weight: 800; letter-spacing: 0.14em; }
h1 { margin: 8px 0 4px; font-size: clamp(1.8rem, 8vw, 2.35rem); line-height: 1.2; }
.title { margin: 0; color: #527c70; font-size: 1rem; font-weight: 650; }
.divider { display: flex; justify-content: center; gap: 7px; margin: 22px 0; }
.divider span { width: 8px; height: 8px; background: #f5ad68; }
.bio-label { display: block; }
.bio { min-height: 76px; margin: 10px 0 0; padding: 10px; border: 2px dashed #b6cfc4; color: #45445d; line-height: 1.55; text-align: left; }
.editable { border-radius: 2px; cursor: text; overflow-wrap: anywhere; }
.editable:hover { background: #fff0d8; }
.editable:focus { outline: 3px solid #f5ad68; outline-offset: 3px; background: #fff0d8; }
.counter { margin: 7px 0 0; color: #6d6b80; font-size: 0.85rem; text-align: right; }
.actions { display: flex; justify-content: center; gap: 12px; margin-top: 22px; }
.button { min-width: 112px; min-height: 46px; padding: 10px 18px; border: 3px solid #252443; border-radius: 0; font: inherit; font-weight: 750; cursor: pointer; transition: transform 100ms, box-shadow 100ms, background-color 100ms; }
.button-primary { color: #fffaf0; background: #527c70; box-shadow: 3px 3px 0 #252443; }
.button-secondary { color: #252443; background: #fffaf0; box-shadow: 3px 3px 0 #252443; }
.button:hover { transform: translate(-1px, -1px); box-shadow: 4px 4px 0 #252443; }
.button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #252443; }
.button:focus-visible { outline: 3px solid #f5ad68; outline-offset: 4px; }
.status { min-height: 1.5em; margin: 14px 0 0; color: #527c70; font-weight: 750; }
@media (max-width: 380px) { .card { padding-top: 24px; padding-bottom: 22px; } .button { min-width: 0; flex: 1; } }

const fields = [...document.querySelectorAll('.editable')];
const bio = document.querySelector('#bio');
const counter = document.querySelector('#counter');
const status = document.querySelector('#status');
const saveButton = document.querySelector('#save');
const cancelButton = document.querySelector('#cancel');
const maxBioLength = 120;
let savedValues = fields.map(field => field.textContent);

function limitBio() {
  const selection = window.getSelection();
  const range = selection && selection.rangeCount ? selection.getRangeAt(0) : null;
  const offset = range && bio.contains(range.startContainer) ? range.startOffset : null;
  if (bio.textContent.length > maxBioLength) {
    bio.textContent = bio.textContent.slice(0, maxBioLength);
    if (offset !== null) {
      const textNode = bio.firstChild;
      if (textNode) {
        const nextRange = document.createRange();
        nextRange.setStart(textNode, Math.min(offset, textNode.length));
        nextRange.collapse(true);
        selection.removeAllRanges();
        selection.addRange(nextRange);
      }
    }
  }
  counter.textContent = `${bio.textContent.length} / ${maxBioLength}`;
}

bio.addEventListener('input', limitBio);
fields.forEach(field => {
  field.addEventListener('input', () => { status.textContent = ''; });
  field.addEventListener('keydown', event => {
    if (field !== bio && event.key === 'Enter') {
      event.preventDefault();
      field.blur();
    }
  });
});

saveButton.addEventListener('click', () => {
  limitBio();
  savedValues = fields.map(field => field.textContent);
  status.textContent = 'Saved';
});

cancelButton.addEventListener('click', () => {
  fields.forEach((field, index) => { field.textContent = savedValues[index]; });
  limitBio();
  status.textContent = 'Changes canceled';
});

limitBio();
